contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum, address _log, uint _newMinSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedSetMinSum;
        c.SetMinSum(_newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedSetMinSum = true;
        } else {
            revertedSetMinSum = false;
        }

        bool revertedSetLogFile;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedSetLogFile = true;
        } else {
            revertedSetLogFile = false;
        }

        assert(revertedSetMinSum && revertedSetLogFile);
    }

    receive() external payable {}
}

